import { FormField, type FormFieldConfig } from "@/components/formfield";
import { particleTerrainGeometry } from "@/components/formfield/geometries/particle-terrain";

const ParticleTerrainFieldGeometries = [particleTerrainGeometry] as const;

export const ParticleTerrainFieldConfig = {
  "version": 1,
  "shape": "particle-terrain",
  "theme": {
    "background": "#000000",
    "star": "#FFFFFF",
    "glow": "#FFFFFF"
  },
  "motion": {
    "flowSpeed": 1,
    "pointScale": 1,
    "morphDuration": 1.35
  },
  "effects": {
    "hoverRadius": 220,
    "hoverIntensity": 1,
    "trailIntensity": 1
  },
  "interaction": {
    "enabled": false,
    "holdMode": "magnet"
  },
  "content": {
    "text": "形场实验室"
  }
} satisfies FormFieldConfig;

export function ParticleTerrainField() {
  return (
    <div style={{ width: "100%", minHeight: 420, aspectRatio: "1 / 1" }}>
      <FormField config={ParticleTerrainFieldConfig} geometries={ParticleTerrainFieldGeometries} />
    </div>
  );
}
